const items = $input.all();
const results = [];

for (const item of items) {
  const html = (item.json.data || item.json.body || '').toString();
  const text = html
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  // Extract pricing mentions
  const priceMatches = text.match(/\$[\d,]+(?:\.\d{2})?(?:\/\w+)?/g) || [];

  // Extract feature-like phrases
  const features = text.match(/(?:new|introducing|launch|announce|update)[^.]{10,80}\./gi) || [];

  // Extract headings for structure changes
  const headings = [];
  const hRegex = /<h[1-3][^>]*>(.*?)<\/h[1-3]>/gi;
  let m;
  while ((m = hRegex.exec(html)) !== null) {
    headings.push(m[1].replace(/<[^>]*>/g, '').trim());
  }

  results.push({
    json: {
      competitor: item.json.competitor || item.json.name || 'Unknown',
      url: item.json.url || '',
      contentSnapshot: text.substring(0, 3000),
      prices: priceMatches,
      newFeatures: features.map(f => f.trim()),
      headings: headings.slice(0, 15),
      fetchedAt: new Date().toISOString()
    }
  });
}

return results;
